entries[53351] = { ["name"] = "Tödlicher Schuss", ["text"] = "45 Meter Reichweite\nSofort 10 sek. Abklingzeit\nBenötigt Distanzwaffe\nIhr versucht, ein verwundetes Ziel zu töten, indem Ihr einen weitreichenden Schuss abfeuert, der 420% Waffenschaden verursacht. Die Fähigkeit 'Tödlicher Schuss' kann nur verwendet werden, wenn das Ziel über 20% Gesundheit oder weniger verfügt.\n\nWenn 'Tödlicher Schuss' das Ziel nicht tötet, wird die Abklingzeit der Fähigkeit sofort abgeschlossen. Dieser Effekt kann nur einmal alle 6 Sek. auftreten." }
entries[53353] = { ["name"] = "Schimärenschuss", ["text"] = "100 Meter Reichweite\nSofort\nEin sofortiger Schuss, der 265% Distanzwaffenschaden als Naturschaden plus 0 verursacht und die Dauer Eures auf das Ziel wirkenden Effekts von 'Schlangengift' auffrischt. Dabei werdet Ihr um [ Glyphe 'Schimärenschuss' : 7 / 5]% Eurer gesamten Gesundheit geheilt. Außerdem wird das Ziel mit dem Effekt 'Mal des Jägers' belegt." }
entries[53354] = { ["name"] = "Manaregeneration erhöht", ["text"] = "Stellt alle 5 Sek. 28 Mana wieder her." }
entries[53355] = { ["name"] = "Stärke der Wildherzen", ["text"] = "Sofort\nEntfesselt die geheime Stärke der Wildherzen. Der Trinkende verfällt in einen heftigen Rausch, der seinen Schmerzwiderstand stark erhöht und ihn unglaublich starke Schläge austeilen lässt." }
