entries[53373] = { ["name"] = "Donnerbräus Starkbier", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt 7199 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[53376] = { ["name"] = "Geweihter Zorn", ["text"] = "'Zornige Vergeltung' hält 50% länger an und macht eine Eurer Fähigkeiten häufiger verfügbar, während der Effekt anhält.\n\nHeilig\nVerringert die Abklingzeit von 'Heiliger Schock' um 50% und erhöht die kritische Trefferchance des Zaubers um 20%.\n\nSchutz\nVerringert die Abklingzeit von 'Richturteil' um 50% und sorgt dafür, dass 'Richturteil' eine weitere Aufladung heiliger Kraft erzeugt. 'Zornige Vergeltung' erhöht außerdem die erhaltene Heilung um 20%.\n\nVergeltung\nVerringert die Abklingzeit von 'Hammer des Zorns' um 50%." }
entries[53385] = { ["name"] = "Göttlicher Sturm", ["text"] = "3 Heilige Kraft\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin Flächenangriff, der 3 Aufladungen heiliger Kraft verbraucht, um allen Gegnern im Umkreis von 8 Metern 100% Waffenschaden als Heiligschaden zuzufügen. [ Glyphe 'Göttlicher Sturm' : Der Einsatz von 'Göttlicher Sturm' heilt Euch zudem um 5% Eurer maximalen Gesundheit ]" }
