entries[53534] = { ["name"] = "Eisketten", ["text"] = "20 Meter Reichweite\nSofort\nFriert das Ziel 3 Sek. lang fest. Während dieser Zeit gilt das Ziel als eingefroren. Nach dem Ausbruch aus den Ketten erhält das Ziel pro Sekunde 10% seines Bewegungstempos zurück." }
entries[53536] = { ["name"] = "Heulende Böe", ["text"] = "20 Meter Reichweite\nSofort\nWeht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern 278 bis 302 Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden." }
entries[53539] = { ["name"] = "Eisstachel" }
entries[53549] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht 86 bis 92 Frostschaden (modifiziert durch Angriffskraft) und verringert bis Abbruch lang das Nahkampfangriffs-, Distanzangriffs- und Zaubertempo des Ziels um 86 bis 92%." }
entries[53550] = { ["name"] = "Gedankenfrost", ["text"] = "Nahkampfreichweite\nSofort\nDie Gedanken des Ziels werden von einer Kälte geschlagen, die 100 Frostschaden verursacht (modifiziert durch Angriffskraft). Das Wirken von Zaubern wird unterbrochen sowie 4 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können." }
entries[53551] = { ["name"] = "Heilige Läuterung", ["text"] = "Euer Zauber 'Läuterung' bannt nun auch Magieeffekte.\nModifies Effect #3's Value +100:\nLäuterung" }
entries[53563] = { ["name"] = "Flamme des Glaubens", ["text"] = "60 Meter Reichweite\nSofort 3 sek. Abklingzeit\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 60 Metern zu einer Flamme des Glaubens.\n\nEs kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein.\n\nFlamme des Glaubens\nWenn Ihr Ziele mit Eurem Zauber 'Heiliges Licht' heilt, wird die Flamme ebenfalls um 100% des geheilten Wertes geheilt. Eure Zauber 'Heiliges Strahlen', 'Licht der Morgendämmerung', 'Hammer des Lichts' und 'Heiliges Prisma' heilen die Flamme um 15% des Wertes. Alle anderen Heilzauber heilen die Flamme um 50% des geheilten Wertes." }
entries[53570] = { ["name"] = "Zehrende Kälte", ["text"] = "10 Meter Reichweite\nSofort\nEntfesselt alle verfügbare Runenmacht, um der Erde unter dem Todesritter jegliche Wärme zu entziehen. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das für 1 Sek. pro 5 Runenmacht jegliche ihrer Aktionen verhindert. Feinde zählen als eingefroren, jeglicher verursachte Schaden unterbricht den Effekt." }
entries[53576] = { ["name"] = "Lichtenergie", ["text"] = "Kritische Effekte Eures Zaubers 'Heiliger Schock' verringern die Zauberzeit Eures nächsten Wirkens von 'Heiliges Licht', 'Göttliches Licht' oder 'Heiliges Strahlen' um 1.50 Sek." }
entries[53592] = { ["name"] = "Vom Licht behütet", ["text"] = "Erhöht Eure gesamte Ausdauer um 25% und Eure Blockchance um 10%.\n\nVerringert die Chance, dass Ihr kritische Nahkampftreffer erleidet, um 6%.\n\nEuer Zauber 'Wort der Herrlichkeit' ist nicht mehr von globaler Abklingzeit betroffen.\n\nEure Zaubermacht entspricht 50% Eurer Angriffskraft und Ihr profitiert nicht mehr von anderen Zaubermachtquellen.\n\nGewährt Euch alle 2 Sek. 15% Eures maximalen Manas.\n(Procchance: 10%)" }
entries[53595] = { ["name"] = "Hammer der Rechtschaffenen", ["text"] = "3% von Grundmana Nahkampfreichweite\nSofort 4.5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nSchlägt mit einem Hammer aus Licht nach dem Ziel, der ihm 20% Waffenschaden zufügt und eine Welle aus Licht auslöst, die Gegnern im Umkreis von 8 Metern 35% Waffenschaden als Heiligschaden zufügt und den Effekt 'Kampfesmüdigkeit' verursacht. Gewährt eine Aufladung heiliger Kraft.\n\nKampfesmüdigkeit\nDemoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%." }
entries[53599] = { ["name"] = "Ungeziefer der Anub'ar beschwören" }
entries[53600] = { ["name"] = "Schild der Rechtschaffenen", ["text"] = "3 Heilige Kraft Nahkampfreichweite\nSpontanzauber 1.5 sek. Abklingzeit\nVerpasst dem Ziel sofort einen heftigen Schlag mit Eurem Schild, der 836 Heiligschaden verursacht. Außerdem wird 3 Sek. lang Euer erlittener körperlicher Schaden um (25 *- 1 ; Min 30, Max 80)% verringert und der Effekt 'Bastion der Herrlichkeit' hervorgerufen.\n\nBastion der Herrlichkeit\nErhöht die Heilwirkung Eures nächsten Wirkens von [ Ewige Flamme : 'Ewige Flamme' / 'Wort der Herrlichkeit'], wenn der Zauber auf Euch selbst gewirkt wird, um 10%. [ Selbstloser Heiler : 'Selbstloser Heiler' erhöht ebenfalls Eure Selbstheilung mit 'Lichtblitz' um 20% pro Stapel ] Bis zu 5-mal stapelbar." }
entries[53602] = { ["name"] = "Hervorschießen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchießt schnell auf einen Feind zu, verursacht 12 Sek. lang alle 3 Sek. 750 Schaden." }
