entries[53605] = { ["name"] = "Degeneration", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an, verursacht 60% Waffenschaden und eine Krankheit, die im Verlauf von 21 Sek. 1400 Schaden zufügt. Alle auf das Ziel wirkenden, Heilung über Zeit verursachenden Effekte werden verderbt und erhöhen den verursachten Schaden der Krankheit dramatisch. Der Heileffekt wird dabei entfernt." }
