entries[53634] = { ["name"] = "Stampfen", ["text"] = "Wirken in 1 sek. 5 sek. Abklingzeit\nStampft auf den Boden auf, verursacht bei Feinden in einem großen Umkreis körperlichen Schaden und schleudert sie in die Luft." }
entries[53635] = { ["name"] = "Umarmung des Todes", ["text"] = "Sofort\nSchlägt alle Gegner in der Nähe, verursacht dabei 13125 bis 16875 Schaden und heilt alle Verbündeten in der Nähe um 13125 bis 16875." }
entries[53636] = { ["name"] = "Antimagisches Feld", ["text"] = "10 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppenmitglieder um 75% verringert. Das antimagische Feld hält entweder 3 Sek. lang an oder bis es 0 Zauberschaden absorbiert hat." }
