entries[54785] = { ["name"] = "Dämonischer Sprung", ["text"] = "Sofort\nBenötigt Metamorphose\nSpringt von Dämonenschwingen getragen einige Meter nach vorn.\n\nDurch die Nutzung dieser Fähigkeit wird 'Metamorphose' aktiviert." }
entries[54786] = { ["name"] = "Dämonischer Sprung", ["text"] = "Unbegrenzte Reichweite\nSofort 45 sek. Abklingzeit\nSpringt bis zu 16 Meter vor Euch durch die Luft und schmettert auf alle Feinde im Umkreis von 5 Metern um das Zielgebiet hinab, verursacht 1 Schattenschaden und betäubt sie 2 Sek. lang." }
entries[54788] = { ["name"] = "Icefang Begin Pathing" }
entries[54790] = { ["name"] = "Blutwandlung", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht körperlichen Schaden und erhöht 15 Sek. lang den verursachten Schaden um 15%." }
entries[54791] = { ["name"] = "Frostblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 2 sek.\nFügt einem Gegner Frostschaden zu und verringert 4 Sek. lang sein Bewegungstempo." }
entries[54792] = { ["name"] = "Eisige Adern", ["text"] = "3% von Grundmana\nSofort\nBeschleunigt Euer Wirken von Zaubern und erhöht dadurch das Zaubertempo um 20%. Hält 20 Sek. lang an." }
entries[54793] = { ["name"] = "Bombengürtel", ["text"] = "Wirken in 5 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt einen Miniatursprengstoffbausatz an Eurem Gürtel an, der es Euch erlaubt, jede Minute eine Thermalbombe abzunehmen und zu werfen.\n\nDie Thermalbombe verursacht ( 75 * 10) bis ( 100 * 10) Feuerschaden und macht Ziele in einem Umkreis von 3 Metern 3 Sek. lang handlungsunfähig." }
entries[54794] = { ["name"] = "Spott", ["text"] = "Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[54795] = { ["name"] = "Voodooflammen", ["text"] = "30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nUmgibt den Zaubernden mit einem Flammenschild, der alle 3 Sek. in der Nähe befindlichen Feinden 57 Feuerschaden zufügt. Hält 15 Sek. lang an." }
entries[54796] = { ["name"] = "Flammenpfeil (ALT)", ["text"] = "30 - 80 Meter Reichweite\nSofort 2 sek. Abklingzeit\nSchießt einen Flammenpfeil." }
entries[54797] = { ["name"] = "Wirbelwind", ["text"] = "Kanalisiert (Wirken in 2 sek.)\nGreift Gegner in der Nähe mit einem Wirbel aus Stahl an, der 2 Sek. lang anhält und normalen Schaden plus 110 verursacht." }
entries[54798] = { ["name"] = "FLAMING Arrow Triggered Effect" }
entries[54799] = { ["name"] = "Frost Giant Kill Credit (Thru Vehicle)" }
entries[54801] = { ["name"] = "Anstürmen", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nStürmt 40 Meter durch in einer Reihe befindliche Gegner vor und durchnässt sie mit Mojo." }
entries[54804] = { ["name"] = "Frostworg Kill Credit (Thru Vehicle)" }
entries[54805] = { ["name"] = "Gedankenschinden", ["text"] = "35 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nFügt einem Gegner Schattenschaden zu und verringert 6 Sek. lang sein Bewegungstempo." }
entries[54806] = { ["name"] = "Arkane Macht-Trigger" }
entries[54808] = { ["name"] = "Schallschild", ["text"] = "Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 2078 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten.\n(Procchance: 50%, 50s Abklingzeit)" }
entries[54810] = { ["name"] = "Glyphe 'Rasende Regeneration'", ["text"] = "Nach der Aktivierung von 'Rasende Regeneration' sind auf Euch gewirkte Heileffekte 6 Sek. lang 40% mächtiger. Allerdings kostet Eure 'Rasende Regeneration' nun immer 50 Wut und wandelt Wut nicht mehr in Gesundheit um." }
entries[54811] = { ["name"] = "Glyphe 'Zermalmen'", ["text"] = "Eure Fähigkeit 'Zermalmen' trifft 1 zusätzliches Ziel für 50% des Schadens." }
entries[54812] = { ["name"] = "Glyphe 'Omen'", ["text"] = "Während kein Finsterniszustand aktiv ist, gewähren Euch die folgenden Fähigkeiten 10 Solar- oder Lunarenergie: 'Wucherwurzeln', 'Wirbelsturm', 'Feenfeuer', 'Feenschwarm', 'Massenumschlingung', 'Taifun', 'Desorientierendes Gebrüll', 'Ursols Vortex' und 'Mächtiger Hieb'." }
